import 'package:slint/slint_core.dart';
import 'package:slint_generator/runtime.dart';

import 'interpreter_engine.dart';
import 'loader.dart';

/// Interpreter backend for the wrappers generated by `slint_generator`:
/// compiles the `.slint` source embedded in the wrapper at runtime.
///
/// ```dart
/// final app = await TodoApp.create(SlintInterpreterFactory());
/// ```
final class SlintInterpreterFactory extends SlintComponentFactory {
  /// Uses [engine] when given — otherwise creates (and owns) one.
  SlintInterpreterFactory([InterpreterSlintEngine? engine])
      : _engine = engine ?? InterpreterSlintEngine(),
        _ownsEngine = engine == null {
    // Touching any interpreter API is enough to make SlintComponent.load work.
    useSlintInterpreter();
  }

  final InterpreterSlintEngine _engine;
  final bool _ownsEngine;

  @override
  Future<SlintSoftwareComponent> instantiate(
    String source,
    String componentName,
  ) async {
    final defs = await _engine.compile(source, path: '$componentName.slint');
    try {
      for (final def in defs) {
        if (def.name == componentName) {
          return def.instantiate();
        }
      }
      throw StateError(
        "no component named '$componentName' in the compiled source "
        '(found: ${defs.map((d) => d.name).join(', ')})',
      );
    } finally {
      for (final def in defs) {
        def.dispose();
      }
    }
  }

  /// Frees the engine, if this factory created it. Components already
  /// instantiated keep working; dispose them separately.
  void dispose() {
    if (_ownsEngine) {
      _engine.dispose();
    }
  }
}
